// 候选人入库后的身份去重规则检查：简历 — 由 Agent 工厂从本体动作 `ruleCheckForCandidateIdentity`(zhaopin)生成。
// trigger: RESUME_PROCESSED → emit: CANDIDATE_IDENTITY_CHECKED
// 参考脚手架：运行时按 workflow manifest 的 action[] 声明式调度执行（systemPrompt + 工具），
// 【不直接运行这段 .ts 代码】——它是可读/可改的 agent 定义参考。真·CodeAct 执行路径用 codeExecuted 开关（默认关）。

/** Input/Output schema — 依据本体 DataObjects 定义。 */
interface RuleCheckForCandidateIdentityAgentInput {
  candidate_id: string; // 候选人ID (源: Candidate.candidate_id)
  resume_id: string; // 简历ID (源: Resume.resume_id)
}

interface RuleCheckForCandidateIdentityAgentOutput {
  candidate_id: string; // 候选人ID (源: Candidate.candidate_id)
  same_person: boolean; // 是否与已有候选人为同一人
}

/** System prompt — 工厂为【这一个】agent 亲自推理出来的。 */
const SYSTEM_PROMPT = `你是一个候选人身份去重规则检查专家。你的职责是在简历解析完成后，按照系统规则对候选人身份进行唯一性判定，确保同一候选人不会被重复建档。

工作流程：
1. 接收 RESUME_PROCESSED 事件，获取 candidate_id 和 resume_id。
2. 调用 ontology.fetchActionRules 动态获取当前生效的候选人身份判定规则（三级优先级：手机号 > 姓名+邮箱 > 六字段组合）。
3. 调用 candidateDedupLookup 按规则逐级比对，判断本次候选人是否与已有候选人为同一人：
   - 第一级：手机号完全匹配 → 判定为同一人。
   - 第二级：姓名+邮箱同时匹配 → 判定为同一人。
   - 第三级：六字段（姓名+出生年月+性别+最高学历+毕业院校+专业）匹配 → 判定为同一人。
   - 以上均不匹配 → 判定为新候选人。
4. 调用 fs.appendToLog 记录判定结果（审计日志）。
5. 产出 CANDIDATE_IDENTITY_CHECKED 事件，包含 candidate_id 和 same_person（Boolean）。

关键约束：
- 本检查为 soft-fail：即使 candidateDedupLookup 调用失败，也应记录错误并默认输出 same_person=false（建新候选人），不阻断主流程。
- 规则必须从 ontology.fetchActionRules 动态获取，绝不硬编码规则逻辑。
- 判定结果仅供审计，不阻断后续流程。`;

export const ruleCheckForCandidateIdentityAgent = defineAgent({
  id: "zhaopin-rule-check-for-candidate-identity",
  name: "RuleCheckForCandidateIdentityAgent",
  actor: ["Agent"],
  trigger: ["RESUME_PROCESSED"],
  emit: ["CANDIDATE_IDENTITY_CHECKED"],
  tools: ["candidateDedupLookup","ontology.fetchActionRules","fs.appendToLog"],
  systemPrompt: SYSTEM_PROMPT,
  async handler(input, ctx) {
      // 调用工具 candidateDedupLookup
      // const candidateDedupLookupResult = await ctx.tools.run("candidateDedupLookup", input);
      // 调用工具 ontology.fetchActionRules
      // const fetchActionRulesResult = await ctx.tools.run("ontology.fetchActionRules", input);
      // 调用工具 fs.appendToLog
      // const appendToLogResult = await ctx.tools.run("fs.appendToLog", input);
      // 用本 agent 专属 system prompt 推理(决策核心)
      const decision = await ctx.reason(SYSTEM_PROMPT, input);
      await ctx.emit("CANDIDATE_IDENTITY_CHECKED", { ...input, ...decision });
      return { ok: true };
  },
});
